import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        # Store balances in cents to prevent floating point inaccuracies
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be greater than zero.")

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)

        if not parts:
            return

        # Convert amount to total cents
        total_cents = round(amount * 100)

        n = len(parts)
        share_cents = total_cents // n

        # Every other participant owes exactly the amount rounded down to the cent.
        # The payer pays total_cents upfront.
        self._balances[payer] = self._balances.get(payer, 0) + total_cents

        for p in parts:
            if p == payer:
                # Leftover cents are borne by the payer:
                # payer's share = share_cents + (total_cents % n)
                # which equals total_cents - (n - 1) * share_cents.
                payer_share = total_cents - (n - 1) * share_cents
                self._balances[p] = self._balances.get(p, 0) - payer_share
            else:
                self._balances[p] = self._balances.get(p, 0) - share_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: round(self._balances[m] / 100.0, 2) for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors have negative balance, creditors have positive balance
        # Debts strictly less than 1.00 (i.e. < 100 cents) are written off
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self.members:
            cents = self._balances[m]
            if cents <= -100:
                debtors.append([m, -cents])
            elif cents >= 100:
                creditors.append([m, cents])

        transactions: list[tuple[str, str, float]] = []

        # Standard two-pointer greedy matching produces at most (N - 1) payments
        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor_name, debt_amount = debtors[d_idx]
            creditor_name, cred_amount = creditors[c_idx]

            transfer = min(debt_amount, cred_amount)

            # Any proposed payment must be >= 1.00 (100 cents)
            if transfer >= 100:
                transactions.append(
                    (debtor_name, creditor_name, round(transfer / 100.0, 2))
                )

            debtors[d_idx][1] -= transfer
            creditors[c_idx][1] -= transfer

            if debtors[d_idx][1] < 100:
                d_idx += 1
            if creditors[c_idx][1] < 100:
                c_idx += 1

        return transactions
